function seoLongForm(topic, pillar = false) {
  const sections = seoDepthThemes.slice(0, 7).map(([heading, focus], index) => `<section class="article-seo-depth"><h2 class="article-heading">${index + 1}. ${heading}</h2><p>Đối với ${topic.toLowerCase()}, ${heading.toLowerCase()} không nên được xem là một việc làm cho có. Gia chủ và đơn vị triển khai cần cùng làm rõ ${focus}. Khi các thông tin này được ghi nhận từ đầu, phương án đề xuất sẽ bám sát điều kiện sử dụng thay vì chỉ đẹp trên hình ảnh tham khảo. Đây cũng là cơ sở để các quyết định sau đó có cùng một tiêu chuẩn đánh giá.</p><p>Một cách làm hiệu quả là ưu tiên theo mức độ ảnh hưởng: việc nào tác động đến an toàn, công năng, chất lượng hoàn thiện và chi phí cần được chốt trước; các chi tiết trang trí có thể phát triển sau. Mọi thay đổi nên được xác nhận bằng bản vẽ, mẫu hoặc biên bản ngắn để tránh hiểu khác nhau. Cách phối hợp này giúp quá trình triển khai chủ động hơn, hạn chế làm lại và giữ trải nghiệm sử dụng lâu dài cho gia đình.</p></section>`).join('');
  const pillarSections = pillar ? seoDepthThemes.slice(7).map(([heading, focus], index) => `<section class="article-seo-depth"><h2 class="article-heading">${index + 8}. ${heading}</h2><p>Ở giai đoạn ${heading.toLowerCase()}, nội dung ${topic.toLowerCase()} cần được kiểm tra theo điều kiện công trình thay vì áp dụng một khuôn mẫu có sẵn. Các bên nên rà soát ${focus}, đồng thời xác định người phụ trách và thời điểm xác nhận. Cách làm này giúp những chi tiết tưởng nhỏ được giải quyết sớm, tránh dồn vấn đề đến ngày lắp đặt hoặc bàn giao.</p><p>Hãy lưu lại các quyết định quan trọng bằng hình ảnh mẫu, ghi chú kỹ thuật hoặc biên bản thống nhất. Tài liệu này giúp gia chủ dễ theo dõi, đội ngũ triển khai có căn cứ thực hiện và việc bảo hành sau này minh bạch hơn. Khi chất lượng được kiểm soát theo từng mốc, kết quả cuối cùng không chỉ đẹp về hình thức mà còn bền bỉ, thuận tiện và đúng với kỳ vọng sử dụng.</p></section>`).join('') : '';
  const pillarConclusion = pillar ? `<section class="article-seo-depth"><h2 class="article-heading">Kinh nghiệm để dự án đạt hiệu quả lâu dài</h2><p>Một dự án nội thất thành công là sự kết hợp giữa thẩm mỹ, kỹ thuật và cách tổ chức công việc. Gia chủ nên dành thời gian ở những mốc có ảnh hưởng lớn: khảo sát hiện trạng, duyệt mặt bằng, chốt vật liệu, xác nhận hồ sơ kỹ thuật và nghiệm thu. Mỗi mốc được thực hiện kỹ sẽ giảm áp lực cho mốc tiếp theo, đồng thời giúp ngân sách và thời gian được kiểm soát thực tế hơn.</p><p>Sau khi đưa vào sử dụng, hãy quan sát cách các thành viên di chuyển, cất đồ, nấu ăn, nghỉ ngơi hoặc làm việc. Những ghi nhận này rất hữu ích cho việc điều chỉnh nhỏ, bảo dưỡng định kỳ và các đợt nâng cấp sau. Cách tiếp cận có kế hoạch sẽ giúp không gian luôn phù hợp với nhịp sống thay đổi, thay vì chỉ đẹp ở thời điểm vừa hoàn thiện.</p><p>Trong thực tế, gia chủ có thể lập một danh sách ưu tiên theo ba nhóm: việc phải hoàn thành trước khi sản xuất, việc cần xác nhận khi lắp đặt và việc theo dõi trong thời gian sử dụng. Ví dụ, kích thước thiết bị, vị trí ổ cắm, cao độ bàn bếp hoặc loại phụ kiện là các thông tin cần chốt sớm. Khi nhận bàn giao, hãy kiểm tra lại thao tác mở tủ, ánh sáng, độ thuận tiện của lối đi và hướng dẫn bảo quản. Một vài phút kiểm tra có hệ thống giúp phát hiện sớm những điểm cần tinh chỉnh, đồng thời tạo nền tảng rõ ràng cho việc bảo hành và chăm sóc công trình về sau.</p></section>` : '';
  return `${sections}${pillarSections}${pillarConclusion}<section class="article-seo-depth"><h2 class="article-heading">Lưu ý khi áp dụng vào công trình thực tế</h2><p>Mỗi không gian có hiện trạng, ngân sách và nhịp sống riêng nên không có một công thức duy nhất cho mọi dự án. Trước khi lựa chọn giải pháp, hãy đối chiếu lại nhu cầu sử dụng, bản vẽ kỹ thuật, mẫu vật liệu và tiến độ của chính công trình. Việc trao đổi minh bạch với kiến trúc sư, bộ phận kỹ thuật và đội thi công sẽ giúp các quyết định được thực hiện đồng bộ, tạo nên kết quả bền đẹp, dễ sử dụng và phù hợp với mục tiêu ban đầu.</p></section>`;
}

function article({ intro, image, alt, sections, faqs, conclusion, pillar = false }) {
  const toc = sections.map(s => `<li><a href="#${s.id}">${s.title}</a></li>`).join('');
  const seed = [...intro].reduce((total, char) => total + char.charCodeAt(0), 0) % editorialImagePool.length;
  const rotatedImages = [...editorialImagePool.slice(seed), ...editorialImagePool.slice(0, seed)];
  const supportingImages = rotatedImages.filter(src => src !== image).slice(0, 4);
  const inlineImage = (src, index) => `<figure class="article-image-box article-inline-image"><img src="${src}" alt="${alt} – hình minh họa ${index + 2}" class="article-main-img" loading="lazy" decoding="async" /><figcaption>Hình minh họa không gian và giải pháp nội thất Shome Luxury.</figcaption></figure>`;
  const content = sections.map((s, index) => `<section><h2 id="${s.id}" class="article-heading">${s.title}</h2>${s.paragraphs.map(p => `<p>${p}</p>`).join('')}${s.bullets ? `<ul class="article-list">${s.bullets.map(item => `<li>${item}</li>`).join('')}</ul>` : ''}${supportingImages[index] ? inlineImage(supportingImages[index], index) : ''}</section>`).join('');
  const remainingImages = supportingImages.slice(sections.length).map((src, index) => inlineImage(src, sections.length + index)).join('');
  const extendedContent = seoLongForm(alt, pillar);
  const faq = faqs.map(item => `<h3>${item.q}</h3><p>${item.a}</p>`).join('');
  return `<div class="old-web-article"><p class="article-intro">${intro}</p><div class="article-image-box"><img src="${image}" alt="${alt}" class="article-main-img" /></div><div class="ftoc-box"><div class="ftoc-header"><span class="ftoc-icon">☰</span><span class="ftoc-title">Nội dung chính</span></div><ol class="ftoc-list">${toc}<li><a href="#faq">Câu hỏi thường gặp</a></li></ol></div>${content}${remainingImages}${extendedContent}<section><h2 id="faq" class="article-heading">Câu hỏi thường gặp</h2>${faq}</section><p><strong>${conclusion}</strong></p></div>`;
}

